-- Part 2: hand-written. Checks, RLS, grants, the unauthenticated pairing lookup.
ALTER TABLE agent_devices
  ADD CONSTRAINT agent_devices_platform_check CHECK (platform IN ('WINDOWS', 'MACOS', 'LINUX', 'OTHER')),
  ADD CONSTRAINT agent_devices_name_check CHECK (length(btrim(name)) > 0);
ALTER TABLE agent_pairing_codes
  ADD CONSTRAINT agent_pairing_codes_hash_check CHECK (code_hash ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT agent_pairing_codes_expiry_check CHECK (expires_at > created_at AND expires_at <= created_at + interval '10 minutes');
ALTER TABLE offline_sync_batches
  ADD CONSTRAINT offline_sync_batches_accepted_check CHECK (accepted >= 0 AND accepted <= 1440);

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['agent_devices', 'agent_pairing_codes', 'offline_sync_batches'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;
-- Devices are revoked, never deleted by the app; sync batches are append-only evidence.
GRANT SELECT, INSERT, UPDATE ON agent_devices TO hrvo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON agent_pairing_codes TO hrvo_app;
GRANT SELECT, INSERT ON offline_sync_batches TO hrvo_app;
REVOKE DELETE, TRUNCATE ON agent_devices, offline_sync_batches FROM hrvo_app;
REVOKE UPDATE ON offline_sync_batches FROM hrvo_app;

-- The agent pairs before it has a tenant context (like refresh and password reset).
CREATE FUNCTION fn_lookup_agent_pairing(p_code_hash VARCHAR)
RETURNS TABLE (
  id UUID,
  org_id UUID,
  user_id UUID,
  expires_at TIMESTAMPTZ,
  used_at TIMESTAMPTZ,
  user_status VARCHAR,
  email VARCHAR,
  display_name VARCHAR,
  role VARCHAR,
  team_id UUID
)
SECURITY DEFINER
SET search_path = public
LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY
  SELECT c.id, c.org_id, c.user_id, c.expires_at, c.used_at, u.status, u.email, u.display_name, u.role, u.team_id
  FROM agent_pairing_codes c
  JOIN users u ON u.id = c.user_id
  WHERE c.code_hash = p_code_hash;
END;
$$;
REVOKE ALL ON FUNCTION fn_lookup_agent_pairing(VARCHAR) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_lookup_agent_pairing(VARCHAR) TO hrvo_app;

-- FR-ATT-011: the agent's explicit consent is recorded like the other consents.
ALTER TABLE monitoring_consents DROP CONSTRAINT monitoring_consents_type_check;
ALTER TABLE monitoring_consents
  ADD CONSTRAINT monitoring_consents_type_check CHECK (consent_type IN ('MONITORING', 'RECORDING', 'AI', 'DESKTOP_AGENT'));
